const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define two locations
  const point1 = ee.Geometry.Point([-50.925784, 46.694935]);
  const point2 = ee.Geometry.Point([-58.528990, 46.809436]);

  // Date range around September 19, 2019
  const startDate = '2019-09-15';
  const endDate = '2019-09-23';

  // Sentinel-2 collection with cloud masking
  let col = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(startDate, endDate)
    .filterBounds(point1.buffer(50000).union(point2.buffer(50000)))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const imgCount = await col.size().getInfo();
  console.log(`Images found: ${imgCount}`);

  if (imgCount === 0) {
    console.log('No Sentinel-2 images found in date range.');
    console.log('C1');
    return;
  }

  // Get median composite to reduce noise
  let img = col.median();

  // Cloud and shadow masking
  function maskClouds(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    return img.updateMask(qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0)));
  }

  img = maskClouds(img);

  // Calculate turbidity proxy: SSI (Suspended Sediment Index)
  // SSI = (Red + NIR) / Green (higher = more sediment/milky)
  const red = img.select('B4');
  const green = img.select('B3');
  const nir = img.select('B8');

  const ssi = (red.add(nir)).divide(green).rename('SSI');

  // Measure at point 1
  const stats1 = ssi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1,
    scale: 10,
    maxPixels: 1e9
  });

  const val1 = await stats1.get('SSI').getInfo();

  // Measure at point 2
  const stats2 = ssi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2,
    scale: 10,
    maxPixels: 1e9
  });

  const val2 = await stats2.get('SSI').getInfo();

  // Check for valid pixels
  const count1 = await img.select('B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point1,
    scale: 10,
    maxPixels: 1e9
  }).get('B4').getInfo();

  const count2 = await img.select('B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point2,
    scale: 10,
    maxPixels: 1e9
  }).get('B4').getInfo();

  console.log(`Point 1: SSI=${val1 !== null ? val1.toFixed(3) : 'null'}, pixels=${count1}`);
  console.log(`Point 2: SSI=${val2 !== null ? val2.toFixed(3) : 'null'}, pixels=${count2}`);

  // Validation
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking at one or both locations.');
    console.log('C2');
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log('Invalid calculation result.');
    console.log('C3');
    return;
  }

  // Compare: Point 1 more milky than Point 2?
  if (val1 > val2) {
    console.log(`Point 1 (SSI=${val1.toFixed(3)}) > Point 2 (SSI=${val2.toFixed(3)}): More milky.`);
    console.log('A');
  } else {
    console.log(`Point 1 (SSI=${val1.toFixed(3)}) ≤ Point 2 (SSI=${val2.toFixed(3)}): Less or equally milky.`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
